using CareComply.Domain.Clients;namespace CareComply.Domain.Tests;public sealed class ClientHospitalizationTests{private static readonly DateTimeOffset Now=new(2026,9,5,8,0,0,TimeSpan.Zero);[Fact]public void CreatesOpenAdmission(){var x=ClientHospitalization.Create(Guid.NewGuid(),Guid.NewGuid()," Hennepin Healthcare ",Now,null," Fall evaluation ",null,null,Guid.NewGuid(),Now);Assert.Equal("Hennepin Healthcare",x.HospitalName);Assert.Null(x.DischargedAtUtc);}[Fact]public void RejectsDischargeBeforeAdmission()=>Assert.Throws<ArgumentException>(()=>ClientHospitalization.Create(Guid.NewGuid(),Guid.NewGuid(),"Hospital",Now,Now.AddMinutes(-1),"Reason",null,null,Guid.NewGuid(),Now));}
